started in FY 1950\n\n# From the table:\n# FY 1947: Transfers to F.O.A. and S.I. Trust Fund = .4 million\n# FY 1950: Transfers to F.O.A. and S.I. Trust Fund = 3.6 million\n\nstart_value = 0.4  # FY 1947\nend_value = 3.6   # FY 1950\nyears = 3  # From 1947 to 1950 is 3 years\n\n# CAGR formula: (end/start)^(1/n) - 1\ncagr = (end_value / start_value) ** (1/years) - 1\n\n# Convert to percentage\ncagr_percent = cagr * 100\n\nprint(f'Start value (1947): {start_value} million')\nprint(f'End value (1950): {end_value} million')\nprint(f'Number of years: {years}')\nprint(f'CAGR: {cagr_percent:.2f}%')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
