f FY 1950\n\n# From table: Transfers to F.O.A. and S.I. Trust Fund (in millions)\n# 1947: 0.4\n# 1950: 3.6\n\nstart_value = 0.4\nend_value = 3.6\nn_years = 3  # From FY 1947 to FY 1950 is 3 years\n\n# CAGR = (End/Start)^(1/n) - 1\ncagr = ((end_value / start_value) ** (1 / n_years)) - 1\ncagr_percent = cagr * 100\n\nprint(f'Starting value (FY 1947): {start_value} million')\nprint(f'Ending value (FY 1950): {end_value} million')\nprint(f'Number of years: {n_years}')\nprint(f'CAGR = ({end_value}/{start_value})^(1/{n_years}) - 1')\nprint(f'CAGR = {end_value/start_value}^(0.3333) - 1')\nprint(f'CAGR = {cagr:.4f} - 1')\nprint(f'CAGR = {cagr:.4f}')\nprint(f'CAGR as percent: {cagr_percent:.2f}%')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
